package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.stream.Stream;

import javax.tools.JavaCompiler;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;

import org.junit.jupiter.api.Test;

class CacheCompetitionChecksTest {

	@Test
	void suppliedChecksRunAgainstCurrentSources() throws Exception {
		Path output = Files.createTempDirectory(Path.of("target"), "cache-competition-checks-");
		Path classes = Files.createDirectory(output.resolve("classes"));
		List<Path> sources = new ArrayList<>();
		Path production = Path.of("src/main/java/org/eclipse/rdf4j/sail/lmdb");
		for (String name : List.of("LmdbCache", "AdaptiveSlotCache", "MemoizingSlotCache", "CompactSlotCache",
				"SlotCasCache",
				"SlotCellCache", "SlotSnapshotCache", "ConcurrentCache")) {
			sources.add(production.resolve(name + ".java"));
		}
		try (Stream<Path> files = Files.walk(Path.of("cache-competition/src"))) {
			files.filter(path -> path.toString().endsWith(".java")).sorted().forEach(sources::add);
		}
		Files.write(output.resolve("sources.txt"), sources.stream().map(Path::toString).toList());
		JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
		assertTrue(compiler != null, "The standalone checks require a JDK compiler");
		StringWriter diagnostics = new StringWriter();
		try (StandardJavaFileManager files = compiler.getStandardFileManager(null, null, StandardCharsets.UTF_8)) {
			boolean compiled = compiler.getTask(diagnostics, files, null, List.of("-d", classes.toString()), null,
					files.getJavaFileObjectsFromPaths(sources)).call();
			Files.writeString(output.resolve("compile.log"), diagnostics.toString());
			assertTrue(compiled, () -> "Standalone compilation failed:\n" + diagnostics);
		}
		runCheck(output, classes, "AdaptiveChecks", "PASS TOTAL ", false);
		runCheck(output, classes, "MemoChecks", "PASS MEMO TOTAL ", false);
		runCheck(output, classes, "PortableSmoke", "PASS java.base-only smoke", true);
	}

	private static void runCheck(Path output, Path classes, String name, String summary, boolean portable)
			throws Exception {
		Path log = output.resolve(name + ".log");
		List<String> command = new ArrayList<>();
		command.add(Path.of(System.getProperty("java.home"), "bin", "java").toString());
		command.add("-ea");
		if (portable) {
			command.add("--limit-modules=java.base");
		}
		command.add("-cp");
		command.add(classes.toString());
		command.add("org.eclipse.rdf4j.sail.lmdb." + name);
		Process process = new ProcessBuilder(command)
				.redirectErrorStream(true)
				.redirectOutput(log.toFile())
				.start();
		try {
			assertTrue(process.waitFor(120, TimeUnit.SECONDS), () -> "Check timed out; output: " + read(log));
			String text = Files.readString(log);
			assertEquals(0, process.exitValue(), () -> "Supplied checks failed:\n" + text);
			assertTrue(text.contains(summary), () -> "Check summary missing:\n" + text);
			System.out.print(text);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
			}
		}
	}

	private static String read(Path path) {
		try {
			return Files.readString(path);
		} catch (IOException e) {
			return path + " (could not read: " + e + ")";
		}
	}
}
